// Segelboot gegen schwimmende Kisten: Boot unten, Seifenblasen nach oben, Holzkisten kommen von oben.
const BW = 40, BH = 30, BOOT_Y = 575, KW = 44, KH = 40;

export default {
  title: "Segelboot gegen schwimmende Kisten",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    const s = { boat: { x: 140, y: BOOT_Y, w: BW, h: BH }, bubbles: [], kisten: [], dir: 1, rows: 3, hits: 0, safe: 0 };
    for (let r = 0; r < 3; r++) addRow(s, g, r);
    return s;
  },

  update(s, input, g) {
    const b = s.boat;
    if (input.left) b.x -= 4;
    if (input.right) b.x += 4;
    b.x = g.clamp(b.x, 4, g.W - BW - 4);
    if (s.safe > 0) s.safe -= 1;

    // Blasen: hoechstens 3 gleichzeitig, starten in der Bootmitte
    if (input.firePressed && s.bubbles.length < 3) {
      s.bubbles.push({ x: b.x + BW / 2, y: BOOT_Y + BH / 2, r: 6 });
      g.sound("shoot");
    }
    for (const u of s.bubbles) u.y -= 7;
    s.bubbles = s.bubbles.filter((u) => u.y >= g.TOP);

    // Nachschub: alle 120 Frames eine neue Reihe oben, bis 8 Reihen
    if (g.frame > 0 && g.frame % 120 === 0 && s.rows < 8) {
      for (const k of s.kisten) k.y += 50;
      addRow(s, g, 0);
      s.rows += 1;
    }
    if (s.kisten.length === 0) { for (let r = 0; r < 3; r++) addRow(s, g, r); s.rows = 3; }

    // Kisten wandern seitwaerts; am Rand Richtung wechseln und 20 px nach unten
    const v = (0.6 + 0.1 * g.level) * s.dir;
    let edge = false;
    for (const k of s.kisten) {
      k.x += v;
      if ((s.dir > 0 && k.x + KW > g.W - 4) || (s.dir < 0 && k.x < 4)) edge = true;
    }
    if (edge) { s.dir = -s.dir; for (const k of s.kisten) k.y += 20; }

    for (const k of s.kisten) if (k.y + k.h >= g.H - 40) { g.gameOver(); return; }

    // Treffer: Blase und Kiste verschwinden, ein Punkt
    for (const u of s.bubbles) {
      for (const k of s.kisten) {
        if (!k.gone && !u.gone && g.hit(u, k)) {
          u.gone = true; k.gone = true;
          s.hits += 1; g.addScore(1); g.sound("pop");
          if (s.hits % 10 === 0) { g.nextLevel(); g.sound("level"); }
          break;
        }
      }
    }
    s.bubbles = s.bubbles.filter((u) => !u.gone);
    s.kisten = s.kisten.filter((k) => !k.gone);

    // Kiste trifft Boot: ein Leben weg, Kiste weg, kurz unverwundbar
    if (s.safe === 0) {
      for (const k of s.kisten) {
        if (g.hit(k, b)) { k.gone = true; s.safe = 60; g.sound("hurt"); g.loseLife(); break; }
      }
      s.kisten = s.kisten.filter((k) => !k.gone);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const u of s.bubbles) d.emoji("🫧", u.x, u.y, 14);
    for (const k of s.kisten) d.emoji("📦", k.x + KW / 2, k.y + KH / 2, 36);
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) d.emoji("⛵", s.boat.x + BW / 2, s.boat.y + BH / 2, 36);
  }
};

function addRow(s, g, r) {
  for (let c = 0; c < 5; c++) s.kisten.push({ x: 20 + c * 68, y: g.TOP + 30 + r * 50, w: KW, h: KH });
}
